<?php
declare(strict_types=1);
namespace Agora\Controllers;
use Agora\Core\{DB,Http};use Agora\Security\Auth;use Agora\Services\Records;
final class Workspace {
 public Records $records;
 public function __construct(public DB $db,public Auth $auth){$this->records=new Records($db,$auth);}
 public function tasks(string $method,array $b,?string $id=null):array{
  if($method==='GET'){$p=$this->records->page('task');$args=[$this->auth->tenant];$sql="SELECT status,COUNT(*) n FROM agora_records WHERE tenant_id=? AND kind='task'";if($this->auth->assignedOnly()){$sql.=' AND owner_id=?';$args[]=$this->auth->user['id'];}$rows=$this->db->all($sql.' GROUP BY status',$args);$stats=array_column($rows,'n','status');return $p+['resumen'=>['pendientes'=>(int)($stats['pendiente']??0),'hechas'=>(int)($stats['hecha']??0)]];}
  $this->auth->write();if($id){$r=$this->records->get('task',$id,true);$d=$this->records->payload($r);$status=$b['estado']??'';if(!in_array($status,['pendiente','hecha'],true))Http::fail('Estado de tarea inválido.');$d['estado']=$status;unset($d['version']);$this->records->save('task',$id,$d,$r['label'],$status,$r['period']);return ['ok'=>true];}
  $title=Http::text($b,'titulo',250);$date=Http::text($b,'vence',10,false);if($date!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)||!checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4))))Http::fail('Fecha inválida.');$hour=Http::text($b,'hora',5,false);if($hour!==''&&!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/D',$hour))Http::fail('Hora inválida.');
  $contact=$b['contactId']??null;$conv=$b['conversationId']??null;if($contact)$this->records->get('contact',(string)$contact);if($conv)$this->records->get('conversation',(string)$conv);
  $owner=(int)$this->auth->user['id'];if(isset($b['responsableId'])&&$this->auth->user['role']!=='EJECUTIVO'){$this->auth->manage();$owner=Http::integer($b['responsableId'],1,PHP_INT_MAX);if(!$this->db->one('SELECT id FROM agora_users WHERE id=? AND local_tenant_id=? AND active=1',[$owner,$this->auth->tenant]))Http::fail('Responsable no disponible.');}
  $id=bin2hex(random_bytes(12));$d=['id'=>$id,'titulo'=>$title,'detalle'=>Http::text($b,'detalle',2000,false),'vence'=>$date?:null,'hora'=>$hour,'estado'=>'pendiente','responsable'=>$this->auth->user['name'],'responsableId'=>$owner,'origen'=>'manual','contactId'=>$contact,'conversationId'=>$conv,'contacto'=>null];
  $this->records->save('task',$id,$d,$title,'pendiente',substr($date,0,7),$owner);return ['ok'=>true,'id'=>$id];
 }
 public function reports():array{
  $this->auth->financial();$args=[$this->auth->tenant];$condition='';if(isset($_GET['period'])){$condition=' AND period=?';$args[]=Http::period($_GET['period']);}
  $rows=$this->db->all("SELECT period,data FROM agora_records WHERE tenant_id=? AND kind='report'$condition ORDER BY period DESC LIMIT 12",$args);$reports=[];foreach($rows as $r)$reports[$r['period']]=json_decode($r['data'],true);
  return ['reports'=>(object)$reports,'inv'=>$this->db->setting($this->auth->tenant,'invoices',['cols'=>[],'rows'=>[],'sheets'=>[]]),'configuracion'=>(object)$this->db->setting($this->auth->tenant,'monthly',[]),'observaciones'=>(object)$this->db->setting($this->auth->tenant,'observations',[]),'availablePeriods'=>array_column($this->db->all("SELECT period FROM agora_records WHERE tenant_id=? AND kind='report' ORDER BY period DESC LIMIT 120",[$this->auth->tenant]),'period')];
 }
 public function configuration(array $b):array{$this->auth->manage();$period=Http::period($b['periodo']??'');$c=$b['config']??[];if(!is_array($c)||strlen(DB::json($c))>100000)Http::fail('Configuración inválida.');$all=$this->db->setting($this->auth->tenant,'monthly',[]);if(!$c)unset($all[$period]);else $all[$period]=$c;$this->db->saveSetting($this->auth->tenant,'monthly',$all);$this->auth->audit('configuracion.actualizada','ajuste',$period);return ['config'=>(object)$all];}
 public function observation(array $b):array{$this->auth->financial();$this->auth->write();$id=Http::text($b,'id',120);$all=$this->db->setting($this->auth->tenant,'observations',[]);if(($b['resuelta']??false)===true)$all[$id]=['resuelta'=>true,'por'=>$this->auth->user['name'],'ts'=>gmdate('c')];else unset($all[$id]);if(count($all)>5000)Http::fail('Límite de observaciones alcanzado.');$this->db->saveSetting($this->auth->tenant,'observations',$all);$this->auth->audit('observacion.actualizada','calidad',$id);return ['observaciones'=>(object)$all];}
 public function import(array $b):array{
  $this->auth->manage();$kind=$b['kind']??'';
  if($kind==='invoices'){$d=$b['data']??null;if(!is_array($d)||!is_array($d['cols']??null)||!is_array($d['rows']??null)||!is_array($d['sheets']??null)||count($d['cols'])>40||count($d['rows'])>5000||strlen(DB::json($d))>1500000)Http::fail('Tabla de facturas inválida (máximo 5.000 filas).');foreach($d['rows'] as $row)if(!is_array($row)||count($row)!==count($d['cols']))Http::fail('Fila de factura incompatible con sus columnas.');$this->db->saveSetting($this->auth->tenant,'invoices',$d);$this->auth->audit('facturas.importadas','invoice','',['filas'=>count($d['rows'])]);return ['ok'=>true,'imported'=>count($d['rows'])];}

  if($kind==='report'){$period=Http::period($b['period']??'');$d=$b['data']??null;if(!is_array($d)||strlen(DB::json($d))>500000||!isset($d['gc']['title'],$d['gc']['advisors'],$d['gc']['total'],$d['hist']['rows']))Http::fail('Reporte incompleto. Usa el formato documentado.');foreach(['gc','hist','sales','catalog','metas','valor','cierre','ads','varAnual'] as $key)if(!is_array($d[$key]??null))Http::fail('Falta sección del reporte: '.$key);foreach(['hist','sales','catalog','valor','cierre'] as $key)if(!is_array($d[$key]['rows']??null))Http::fail('Tabla inválida: '.$key);if(count($d['hist']['rows'])!==12)Http::fail('El histórico debe incluir doce meses.');foreach(['recaudacion','pupitres','ocupacion'] as $key)if(!is_array($d['metas'][$key]['items']??null))Http::fail('Metas incompletas.');if(!is_array($d['gc']['codes']??null)||!is_array($d['gc']['total'])||!is_array($d['gc']['advisors'])||!count($d['cierre']['rows']))Http::fail('Gestión comercial incompleta.');$this->records->save('report',$period,$d,$period,'',$period);return ['ok'=>true,'period'=>$period];}
  if(!in_array($kind,['contact','opportunity','pipeline'],true))Http::fail('Tipo de importación inválido.');$rows=$b['items']??null;if(!is_array($rows)||!array_is_list($rows)||count($rows)>500)Http::fail('Importa hasta 500 registros por lote.');
  foreach($rows as $r){if(!is_array($r))Http::fail('Registro inválido.');$id=isset($r['id'])?Http::text($r,'id',80):bin2hex(random_bytes(12));if(!preg_match('/^[A-Za-z0-9_-]+$/D',$id))Http::fail('Identificador inválido.');$name=Http::text($r,'name',190);$r['id']=$id;if($kind==='contact'){$r['email']=Http::text($r,'email',254,false);if($r['email']!==''&&!filter_var($r['email'],FILTER_VALIDATE_EMAIL))Http::fail('Correo del contacto inválido.');$r['phone']=Http::text($r,'phone',40,false);$r['tags']=array_values(array_filter($r['tags']??[],'is_string'));}
   if($kind==='opportunity'){$this->records->get('contact',Http::text($r,'contactId',80));$this->records->get('pipeline',Http::text($r,'pipelineId',80));if(!is_numeric($r['monetaryValue']??null)||$r['monetaryValue']<0||$r['monetaryValue']>100000000)Http::fail('Valor inválido.');if(!in_array($r['status']??'open',['open','won','lost','abandoned']))Http::fail('Estado inválido.');}
   if($kind==='pipeline'){if(!is_array($r['stages']??null)||count($r['stages'])>30)Http::fail('Etapas inválidas.');foreach($r['stages'] as $stage){Http::text($stage,'id',80);Http::text($stage,'name',120);}}
   $owner=null;if(isset($r['assignedTo'])){$owner=Http::integer($r['assignedTo'],1,PHP_INT_MAX);if(!$this->db->one('SELECT id FROM agora_users WHERE id=? AND local_tenant_id=? AND active=1',[$owner,$this->auth->tenant]))Http::fail('Responsable fuera de la subcuenta.');}
   $this->records->save($kind,$id,$r,$name.' '.($r['email']??'').' '.($r['phone']??''),$r['status']??'','',$owner);
  }return ['ok'=>true,'imported'=>count($rows)];
 }
 public function contacts(string $method,array $b):array{
  $id=(string)($_GET['contactId']??$b['contactId']??'');$r=$this->records->get('contact',$id,$method!=='GET');$d=$this->records->payload($r);
  if($method!=='GET'){$this->auth->write();foreach(['firstName','lastName','name','email','phone','companyName','address1','city','state','postalCode','country','website'] as $k)if(isset($b[$k]))$d[$k]=Http::text($b,$k,254,false);if(isset($b['tags'])){if(!is_array($b['tags'])||count($b['tags'])>50)Http::fail('Etiquetas inválidas.');$d['tags']=array_map(fn($v)=>Http::text(['tag'=>$v],'tag',80),$b['tags']);}if(isset($b['customFields'])){if(!is_array($b['customFields'])||strlen(DB::json($b['customFields']))>10000)Http::fail('Campos inválidos.');$d['customFields']=$b['customFields'];}if(!empty($d['email'])&&!filter_var($d['email'],FILTER_VALIDATE_EMAIL))Http::fail('Correo inválido.');unset($d['version']);$this->records->save('contact',$id,$d,$d['name']??trim(($d['firstName']??'').' '.($d['lastName']??'')),$r['status'],$r['period'],null,isset($b['version'])?(int)$b['version']:null);}
  return ['contact'=>$d,'fields'=>[],'assignees'=>$this->assignees(),'canEdit'=>!in_array($this->auth->user['role'],['USUARIO','CONSULTA','VISOR'])];
 }
 public function assignees():array{return $this->db->all('SELECT id,name FROM agora_users WHERE local_tenant_id=? AND active=1 ORDER BY id LIMIT 100',[$this->auth->tenant]);}
 public function opportunity(array $b,string $action):array{
  $this->auth->write();$id=$action==='new'?bin2hex(random_bytes(12)):(string)($_GET['opportunityId']??'');$r=$action==='new'?null:$this->records->get('opportunity',$id,true);$d=$r?$this->records->payload($r):['id'=>$id,'contactId'=>(string)($_GET['contactId']??''),'dateAdded'=>gmdate('c'),'status'=>'open'];
  $this->records->get('contact',$d['contactId']);foreach(['name','pipelineId','pipelineStageId','status'] as $k)if(isset($b[$k]))$d[$k]=Http::text($b,$k,190);if(!in_array($d['status'],['open','won','lost','abandoned'],true))Http::fail('Estado inválido.');if(isset($b['monetaryValue'])){if(!is_numeric($b['monetaryValue'])||$b['monetaryValue']<0||$b['monetaryValue']>100000000)Http::fail('Monto inválido.');$d['monetaryValue']=round((float)$b['monetaryValue'],2);}
  $pipe=$this->records->payload($this->records->get('pipeline',(string)($d['pipelineId']??'')));$stages=array_column($pipe['stages']??[],'id');$d['pipelineStageId']=$d['pipelineStageId']??($stages[0]??'');if(!in_array($d['pipelineStageId'],$stages,true))Http::fail('Etapa inválida.');if($d['status']==='won'&&($r['status']??'')!=='won')$d['wonAt']=gmdate('c');unset($d['version']);$this->records->save('opportunity',$id,$d,$d['name']??'Oportunidad',$d['status'],substr($d['wonAt']??$d['dateAdded'],0,7),null,isset($b['version'])?(int)$b['version']:null);return ['ok'=>true,'opportunity'=>$d];
 }
 public function board():array{$pipes=$this->records->page('pipeline')['items'];$pid=(string)($_GET['pipelineId']??($pipes[0]['id']??''));$pipeline=null;foreach($pipes as $p)if($p['id']===$pid)$pipeline=$p;$page=$this->records->page('opportunity',['status'=>'open']);$items=array_values(array_filter($page['items'],fn($o)=>($o['pipelineId']??'')===$pid));$stages=[];foreach($pipeline['stages']??[] as $stage){$rows=array_values(array_filter($items,fn($o)=>($o['pipelineStageId']??'')===$stage['id']));$stages[]=$stage+['items'=>$rows,'total'=>count($rows),'value'=>array_sum(array_column($rows,'monetaryValue'))];}return ['pipelines'=>$pipes,'pipelineId'=>$pid,'stages'=>$stages,'total'=>count($items),'partial'=>$page['hasMore'],'canEdit'=>!in_array($this->auth->user['role'],['USUARIO','CONSULTA','VISOR']),'restricted'=>$this->auth->assignedOnly()];}
}
